import math

def calculate_different_sums(x1, y1, x2, y2):
    # The number of different sums is equal to the Greatest Common Divisor (GCD)
    # of the number of steps to the right and the number of steps down
    return math.gcd(x2 - x1, y2 - y1)

def main():
    t = int(input())
    for _ in range(t):
        x1, y1, x2, y2 = map(int, input().split())
        result = calculate_different_sums(x1, y1, x2, y2)
        print(result)

if __name__ == "__main__":
    main()
